            claimedTotal = claimedTotal.add(claimed);
            overdueTotal = overdueTotal.add(overdue);
            if (personDue != null) {
                dueTotal = dueTotal.add(personDue);
            }
        }
        return new Snapshot(figures, claimedTotal, dueTotal, overdueTotal);
    }

    /** Each person's due-total of their claims that count dated from one date to another, both
     *  inclusive, by person id, every person on the sheet in the order they were added, as the screen
     *  shows a person's for a period: each claim's settled due, else the figure its statement bound,
     *  else its live due, at least the floor, an overdue claim's late charge on top (a claim with no
     *  figure adds nothing). */
    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
        Optional<Sheet> sheet = sheets.findById(sheetId);
        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAsc(sheetId);
        Map<Long, Person> byId = new LinkedHashMap<>();
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        people.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> {
            byId.put(p.getId(), p);
            totals.put(p.getId(), ZERO);
        });
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        for (Claim claim : sheetClaims) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !countsLive(claim, person) || claim.getDate().isBefore(from)
                    || claim.getDate().isAfter(to)) {
                continue;
            }
            BigDecimal due;
            if (claim.getSettledDue() != null) {
                due = claim.getSettledDue();
            } else if (claim.isBound()) {
                due = claim.getStatedDue();
            } else {
                due = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate())
                        .map(rate -> rated(sheet, claim, sheetClaims, rate))
                        .map(d -> floored(sheet, claim, d))
                        .orElse(null);
            }
            if (due != null) {
                totals.merge(person.getId(), charged(sheet, claim, due), BigDecimal::add);
            }
        }
        return totals;
    }

    /** Record, once the change commits, the lines for every figure that moved since {@code before}. */
    public void recordChanges(String sheetId, String user, Snapshot before) {
        Snapshot after = take(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
            Figures was = before.people().get(id);
            if (was == null || was.claimed().compareTo(now.claimed()) != 0
                    || !sameDue(was.dueTotal(), now.dueTotal())
                    || was.overdueTotal().compareTo(now.overdueTotal()) != 0) {
                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
                        + " claimed=" + now.claimed().toPlainString() + " due-total=" + show(now.dueTotal())
                        + " overdue-total=" + now.overdueTotal().toPlainString());
            }
        });
        if (before.claimedTotal().compareTo(after.claimedTotal()) != 0
                || before.dueTotal().compareTo(after.dueTotal()) != 0
                || before.overdueTotal().compareTo(after.overdueTotal()) != 0) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal().toPlainString()
                    + " due-total=" + after.dueTotal().toPlainString()
                    + " overdue-total=" + after.overdueTotal().toPlainString());
        }
    }

    /** Whether a claim counts in the live totals: its status counts, and it is not left out by a hold. */
    private static boolean countsLive(Claim claim, Person person) {
        return claim.getStatus().counts() && !heldOut(claim, person);
    }

    /** Whether a claim is overdue: OPEN or PENDING, with its due-by before the sheet's today. */
    private static boolean overdue(Claim claim, LocalDate today) {
        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
                && claim.getDueBy().isBefore(today);
    }

    /** Whether a hold leaves a claim out of the live totals: it is OPEN or PENDING, bound by no statement,
     *  and dated within one of its person's holds. */
    public static boolean heldOut(Claim claim, Person person) {
        return person != null && claim.getStatus().isOpen() && !claim.isBound() && person.heldOn(claim.getDate());
    }

    /** A claim's amount at a rate, divided by 100, rounded to cents as the claim's rounding date rounds on
     *  the sheet (half to even with no sheet). */
    private static BigDecimal rated(Optional<Sheet> sheet, Claim claim, List<Claim> sheetClaims, Rate rate) {
        LocalDate on = roundingDate(claim, sheetClaims);
        return claim.getAmount().multiply(rate.getRate()).movePointLeft(2)
                .setScale(2, sheet.map(s -> s.rounding(on)).orElse(RoundingMode.HALF_EVEN));
    }

    /** The date a claim's figures round by: its own, or for a correction the date of the claim it
     *  corrects (the claim of the same person with that number), its own when that is not found. */
    public static LocalDate roundingDate(Claim claim, List<Claim> sheetClaims) {
        if (!claim.isCorrection()) {
            return claim.getDate();
        }
        return sheetClaims.stream()
                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
                .findFirst().map(Claim::getDate).orElse(claim.getDate());
    }

    /** A live due as it counts: at least the sheet's floor, unless its claim is a correction. */
    private static BigDecimal floored(Optional<Sheet> sheet, Claim claim, BigDecimal due) {
        return claim.isCorrection() ? due : sheet.map(s -> s.floored(due)).orElse(due);
    }

    /** A figure with its late charge on top while its claim is OPEN or PENDING (only those go overdue); a
     *  settled claim's due already holds the charge frozen in when it was settled. A correction has no
     *  late charge. */
    public static BigDecimal charged(Optional<Sheet> sheet, Claim claim, BigDecimal figure) {
        if (!claim.getStatus().isOpen() || claim.isCorrection()) {
            return figure;
        }
        return figure.add(sheet.map(s -> s.lateCharge(figure, claim.getDueBy(), claim.getDate())).orElse(ZERO));
    }

    /** A person's due-total at most the sheet's cap. */
    private static BigDecimal capped(Optional<Sheet> sheet, BigDecimal dueTotal) {
        return sheet.map(s -> s.capped(dueTotal)).orElse(dueTotal);
    }

    private static boolean sameDue(BigDecimal a, BigDecimal b) {
        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
    }

    private static String show(BigDecimal due) {
        return due == null ? "n/a" : due.toPlainString();
    }

    /** The grade's rate in force on a date: the latest from-date on or before it, none first; none
     *  when the date is after that rate's to-date. */
    private static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
        return sheetRates.stream()
                .filter(r -> r.getGrade().equals(grade))
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.coversThrough(date));
    }
}
        this.statements = statements;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        sheets.today(sheetId);
        return claims.findBySheetIdOrderByListOrderDesc(sheetId);
    }

    /** Add a claim; a negative amount (a correction) must name a SETTLED claim of the person by number,
     *  and a claim of 0.00 or more must name none. */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, on);
        refuseRetired(person, on);
        refuseCorrection(sheetId, personId, amount, corrects);
        Rollup.Snapshot before = rollup.take(sheetId);
        int terms = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new)
                .termsFor(person.gradeOn(on));
        Claim claim = new Claim(sheetId, personId, amount.setScale(2), on, on.plusDays(terms), note, corrects);
        claim.setListOrder(claims.maxListOrder(sheetId) + 1);
        logStatus(claim, person, user);
        claim = claims.saveAndFlush(claim);
        audit("CLAIM_ADDED", claim, person, user);
        rollup.recordChanges(sheetId, user, before);
        return claim;
    }

    /** Change a DRAFT claim; a claim in any other status is refused, and a correction as when added. */
    @Transactional
    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimNotDraftException(claim.getStatus());
        }
        return updated;
    }

    /** Re-settle a SETTLED claim: freeze it again at the figure it would have today as an OPEN claim bound by
     *  no statement (today's rates, grades and floor, the late charge on the sheet's today on top). Refused
     *  unless the claim is SETTLED and the user is a steward, and for a claim in a closed period. */
    @Transactional
    public Claim resettle(String sheetId, String user, long claimId) {
        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDate());
        if (!roles.isSteward(sheetId, user)) {
            throw new ClaimResettleException("Only a steward can re-settle a claim.");
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ClaimResettleException("Only a SETTLED claim can be re-settled.");
        }
        Rollup.Snapshot before = rollup.take(sheetId);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        BigDecimal old = claim.getSettledDue();
        BigDecimal figure = liveDue(claim, person);
        BigDecimal due = figure == null || claim.isCorrection() ? figure
                : figure.add(sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new)
                        .lateCharge(figure, claim.getDueBy(), claim.getDate()));
        claim.setSettledDue(due);
        logStatus(claim, person, user);
        Claim updated = claims.saveAndFlush(claim);
        audit("CLAIM_RESETTLED", updated, person, user, updated.getNumber(),
                " old=" + show(old) + " new=" + show(due));
        rollup.recordChanges(sheetId, user, before);
        return updated;
    }

    /** Reject a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last
     *  statement if that statement included it. Refused unless the claim is PENDING, the user is a
     *  steward and a reason is given. */
        boolean figure = false;
        int counted = 0;
        for (Claim claim : theirs) {
            if (!claim.getStatus().counts() || (claim.getStatus().isOpen() && person.heldOn(claim.getDate()))) {
                claim.setStated(false, null);
                continue;
            }
            BigDecimal due = due(claim, person);
            if (due != null) {
                total = total.add(charged(claim, due));
                figure = true;
            }
            claim.setStated(true, due);
            counted++;
        }
        boolean rated = rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
        BigDecimal summed = total;
        BigDecimal dueTotal = rated || figure
                ? sheetRows.findById(sheetId).map(s -> s.capped(summed)).orElse(summed) : null;
        claims.saveAllAndFlush(theirs);
        statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
        rollup.recordChanges(sheetId, user, before);
        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
    }

    /** Refuse a change to a claim dated inside a closed period. Locks the sheet first, so a period being
     *  closed at the same moment is seen. */
    private void refuseClosed(String sheetId, LocalDate date) {
        sheetRows.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        if (periods.closedOn(sheetId, date)) {
            throw new PeriodClosedException();
        }
    }

    /** Whether a clerk is settling a due above the sheet's clerk limit; a steward settles anything, and a
     *  due of n/a, or a sheet with no limit, is within it. */
    private boolean overLimit(String sheetId, String user, BigDecimal due) {
        BigDecimal limit = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new).getClerkLimit();
        return limit != null && due != null && due.compareTo(limit) > 0 && !roles.isSteward(sheetId, user);
    }

    /** Refuse a negative amount that does not name a SETTLED claim of the person by number, and a claim of
     *  0.00 or more that names one. */
    private void refuseCorrection(String sheetId, long personId, BigDecimal amount, String corrects) {
        if (amount.signum() >= 0) {
            if (corrects != null) {
                throw new ClaimCorrectionException("Only a negative amount corrects a claim.");
            }
            return;
        }
        if (corrects == null) {
            throw new ClaimCorrectionException(
                    "A negative amount is a correction: name the number of the settled claim it corrects.");
        }
        if (!claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
            throw new ClaimCorrectionException("A correction must name a settled claim of the same person.");
        }
    }

    /** Refuse a claim dated after its person's retirement date. */
    private static void refuseRetired(Person person, LocalDate date) {
        if (person.retiredOn(date)) {
            throw new PersonRetiredException();
        }
    }

    /** A claim's figure: the due fixed when settled, else the one its last statement bound (not while
     *  PENDING), else its live due; none when that is n/a. */
    private BigDecimal due(Claim claim, Person person) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
    }

    /** Log the status a claim has just taken: by the user, on the sheet's today, with its due as the
     *  screen shows it now. */
    private void logStatus(Claim claim, Person person, String user) {
        claim.logStatus(user, sheets.today(claim.getSheetId()), shownDue(claim, person));
    }

    /** A claim's due as the screen shows it: fixed when settled, else its figure (bound or live) with its
     *  late charge on top; none when that is n/a. */
    private BigDecimal shownDue(Claim claim, Person person) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        BigDecimal figure = due(claim, person);
        return figure == null ? null : charged(claim, figure);
    }

    /** A claim's figure with its late charge on the sheet's today on top while it is OPEN or PENDING. */
    private BigDecimal charged(Claim claim, BigDecimal figure) {
        return Rollup.charged(sheetRows.findById(claim.getSheetId()), claim, figure);
    }

    /** The claim's amount at the rate in force on its date of its person's grade in force then in force on its date, at least the sheet's floor
     *  (a correction has none); none when no rate applies. */
    private BigDecimal liveDue(Claim claim, Person person) {
        Sheet sheet = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new);
        RoundingMode rounding = sheet.rounding(roundingDate(claim));
        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
                .map(rate -> claim.isCorrection() ? due(claim.getAmount(), rate, rounding)
                        : sheet.floored(due(claim.getAmount(), rate, rounding)))
                .orElse(null);
    }

    /** The date a claim's figures round by: its own, or for a correction the date of the claim it corrects. */
    private LocalDate roundingDate(Claim claim) {
        if (!claim.isCorrection()) {
            return claim.getDate();
        }
        return claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
                .map(Claim::getDate).orElse(claim.getDate());
    }

    /** An amount times a rate, divided by 100, rounded to cents. */
    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
        return amount.multiply(rate.getRate()).movePointLeft(2).setScale(2, rounding);

