-- The sheet's clerk limit: the largest due a clerk may settle (two decimals); none means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(15, 2) CHECK (clerk_limit >= 0);

-- The role the sheet gives a user name: clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200)  NOT NULL,
    role      VARCHAR(20)   NOT NULL CHECK (role IN ('clerk', 'steward'))
);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);
-- The sheet's floor: the least a claim's live due can be (two decimals). A sheet starts at 1.00.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(15, 2) DEFAULT 1.00 NOT NULL CHECK (due_floor >= 0);
-- The sheet's terms: the number of days after a claim's date it is due by. A sheet starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL CHECK (terms >= 0);
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every full 30 days
-- it is overdue. A sheet starts at 0.00.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(9, 2) DEFAULT 0.00 NOT NULL CHECK (late_pct >= 0);
package net.officefloor.hq.app.sheet;

import jakarta.persistence.LockModeType;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** The sheet, locked until the transaction ends, so two users' claim numbers go one after the other. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select s from Sheet s where s.id = :id")
    Optional<Sheet> findForUpdateById(String id);
}

